"""NEBIM KEŞİF 48 — MAĞUSA (S02) 01.09.2026 SAYIMI NEBİM'E İŞLENDİ Mİ? (salt-okunur)

Mağaza 01.09.2026 kapanışından sonra sayıldı. Bu dosyaya "MAGUSA SAYIM 1 EYLUL 2026.xlsx"
gömülüdür (3.001 satır / 5.339 adet; kadın çantalar 10.09 okuması + 02–10.09 satışıyla
güncellenmiş hâli). Her satırda ESKİ dosyadaki adet de var (5.327 adet; 26 çanta satırı farklı).

Soru: Nebim'de S02 deposunun 01.09.2026 kapanış stoğu bu dosyayla aynı mı; yani sayım
"1 Eylül stoğu" olarak işlenmiş mi?

Mantık (ürün bazında, depo S02):
  Stok01Ham = 01.09 kapanış bakiyesi, 02.09'dan sonra GİRİLEN sayım düzeltmeleri (CI/CO) HARİÇ
  DuzGiris  = 02.09'dan sonra girilen CI (Sayım Fazlası Girişi) / CO (Sayım Eksiği Çıkışı) net adedi
  Stok01Duz = Stok01Ham + DuzGiris            → Nebim'in bugün "01.09 stoğu" dediği rakam
  FARK      = Stok01Duz − Sayım               → 0 ise sayım bu ürün için doğru işlenmiş
Bölümler: A) şema  B) CI/CO belgeleri + 02.09+ girilen hareketler  C) barkod→ürün
  D) mutabakat + hüküm + değişen 26 çanta  E) ters kontrol (sayımda yok, Nebim'de var)
  F) tutmayanların son hareketleri  G) CSV
Çıktı: KESIF48-CIKTI.txt, KESIF48-SONUC.csv, KESIF48-TERS.csv   (hiçbir şey YAZMAZ, sadece SELECT)
"""
