OUT = []


def log(*a):
    s_ = " ".join(str(x) for x in a)
    print(s_)
    OUT.append(s_)


def bolum(baslik):
    def dekore(fn):
        def sarili(*a, **k):
            log(f"\n===== {baslik} =====")
            try:
                return fn(*a, **k)
            except Exception:
                log("BÖLÜM HATASI:\n" + traceback.format_exc())
        return sarili
    return dekore


def kolonlar(cur, tablo):
    cur.execute("SELECT COLUMN_NAME, DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS "
                "WHERE TABLE_NAME = ? ORDER BY ORDINAL_POSITION", tablo)
    return [(r[0], r[1]) for r in cur.fetchall()]


def tablo_var(cur, tablo):
    cur.execute("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = ?", tablo)
    return cur.fetchone()[0] > 0


def f(x):
    if x is None:
        return 0.0
    if isinstance(x, Decimal):
        return float(x)
    try:
        return float(x)
    except Exception:
        return 0.0


def s(x):
    return "" if x is None else str(x).strip()


def d(x):
    if x is None:
        return None
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, date):
        return x
    try:
        return datetime.strptime(str(x)[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def chunks(lst, n=900):
    for i in range(0, len(lst), n):
        yield lst[i:i + n]


class Sema:
    st_cols = []
    st_date = None
    st_created = None
    tip_cols = []
    dim2 = False
    docno = None
    ip_idx = None
    tip_aciklama = {}


SEMA = Sema()
URUN = {}           # ürün anahtarı -> dict (sayım, barkodlar …)
ESLESMEYEN = []     # prItemBarcode'da bulunmayan sayım satırları
ACILIS = {}
HAREKET = defaultdict(list)
SATIS = defaultdict(lambda: [0.0, 0.0])
TERS = []


def key_of(row_item, row_color, row_dim1, row_dim2=None):
    # SQL Server harf duyarsız; Python'da da öyle davran (KESIF41 dersi)
    k = (s(row_item).upper(), s(row_color).upper(), s(row_dim1).upper())
    if SEMA.dim2:
        k = k + (s(row_dim2).upper(),)
    return k


def key_cols(alias):
    cols = [f"{alias}.ItemCode", f"{alias}.ColorCode", f"{alias}.ItemDim1Code"]
    if SEMA.dim2:
        cols.append(f"{alias}.ItemDim2Code")
    return cols


def is_adj(t):
    """Sayım düzeltmesi = InnerProcessCode CI (Sayım Fazlası Girişi) / CO (Sayım Eksiği Çıkışı).
    Transfer (S), satış (R) vb. ASLA düzeltme sayılmaz (KESIF41 dersi)."""
    return SEMA.ip_idx is not None and t[SEMA.ip_idx] in ("CI", "CO")


def tip_str(t):
    parts = []
    for c, v in zip(SEMA.tip_cols, t):
        ac = SEMA.tip_aciklama.get((c, s(v)))
        parts.append(f"{c}={s(v)}" + (f"({ac})" if ac else ""))
    return " ".join(parts) if parts else "(tip yok)"


# ---------------------------------------------------------------- A
@bolum("A) ŞEMA")
def a_sema(cur):
    SEMA.st_cols = kolonlar(cur, "trStock")
    names = [c for c, _ in SEMA.st_cols]
    for cand in ("DocumentDate", "TransDate", "StockDate", "OperationDate"):
        if cand in names:
            SEMA.st_date = cand
            break
    if not SEMA.st_date:
        raise RuntimeError("trStock'ta belge tarihi kolonu bulunamadı: " + ", ".join(names))
    SEMA.st_created = "CreatedDate" if "CreatedDate" in names else SEMA.st_date
    SEMA.tip_cols = [c for c in ("TransTypeCode", "ProcessCode", "InnerProcessCode") if c in names]
    SEMA.ip_idx = SEMA.tip_cols.index("InnerProcessCode") if "InnerProcessCode" in SEMA.tip_cols else None
    SEMA.docno = next((c for c in ("DocumentNumber", "InvoiceNumber", "ShipmentNumber", "InnerNumber",
                                   "RefNumber") if c in names), None)
    bk = [c for c, _ in kolonlar(cur, "prItemBarcode")]
    SEMA.dim2 = ("ItemDim2Code" in names) and ("ItemDim2Code" in bk)
    log(f"  belge tarihi: {SEMA.st_date} | giriş tarihi: {SEMA.st_created} | tip: {SEMA.tip_cols} | "
        f"belge no: {SEMA.docno} | Dim2 anahtarda: {SEMA.dim2}")
    for col, tbl, codecol, desccol in (
            ("TransTypeCode", "bsTransTypeDesc", "TransTypeCode", "TransTypeDescription"),
            ("ProcessCode", "bsProcessDesc", "ProcessCode", "ProcessDescription"),
            ("InnerProcessCode", "bsInnerProcessDesc", "InnerProcessCode", "InnerProcessDescription")):
        if col not in SEMA.tip_cols or not tablo_var(cur, tbl):
            continue
        try:
            cur.execute(f"SELECT {codecol}, {desccol} FROM {tbl} WITH(NOLOCK) WHERE LangCode='TR'")
            for r in cur.fetchall():
                SEMA.tip_aciklama[(col, s(r[0]))] = s(r[1])
        except Exception as e:
            log(f"  ({tbl} okunamadı: {str(e)[:80]})")


# ---------------------------------------------------------------- B
@bolum("B) SAYIM DÜZELTME BELGELERİ (CI/CO) VE 02.09+ GİRİLEN HAREKETLER")
def b_belgeler(cur):
    if SEMA.ip_idx is None:
        log("  trStock'ta InnerProcessCode yok — CI/CO aranamıyor")
        return
    docno = SEMA.docno or "TransTypeCode"   # belge no kolonu bulunamazsa gerçek bir kolonla yer tut (GROUP BY NULL olmaz)
    # B1: S02'de 2025'ten beri tüm CI/CO belgeleri
    cur.execute(f"""
        SELECT InnerProcessCode, {docno}, CAST({SEMA.st_date} AS date), MIN({SEMA.st_created}), MAX({SEMA.st_created}),
               COUNT(*), SUM(ISNULL(In_Qty1,0)), SUM(ISNULL(Out_Qty1,0)),
               COUNT(DISTINCT ItemCode + '|' + ColorCode + '|' + ItemDim1Code)
        FROM trStock WITH(NOLOCK)
        WHERE WarehouseCode = ? AND InnerProcessCode IN ('CI','CO') AND {SEMA.st_date} >= '2025-01-01'
        GROUP BY InnerProcessCode, {docno}, CAST({SEMA.st_date} AS date)
        ORDER BY MIN({SEMA.st_created})""", (WH,))
    rows = cur.fetchall()
    log(f"  B1) {WH} deposunda 01.01.2025'ten beri CI/CO belgeleri: {len(rows)}")
    log("   tip | belge no        | belge T    | giriş (ilk → son)                    | satır | +giriş | −çıkış | ürün")
    for r in rows:
        isaret = "  ◀◀ SAYIM SONRASI GİRİLMİŞ" if (d(r[3]) and d(r[3]) >= SONRASI) else ""
        log(f"   {s(r[0]):3} | {s(r[1]):15} | {s(d(r[2])):10} | {s(r[3])[:16]} → {s(r[4])[:16]} | {r[5]:>5} | "
            f"{f(r[6]):>6.0f} | {f(r[7]):>6.0f} | {r[8]:>4}{isaret}")
    sonra = [r for r in rows if d(r[3]) and d(r[3]) >= SONRASI]
    log(f"  → {SONRASI} ve sonrasında GİRİLEN CI/CO belgesi: {len(sonra)} | "
        f"+{sum(f(r[6]) for r in sonra):.0f} giriş, −{sum(f(r[7]) for r in sonra):.0f} çıkış, "
        f"{sum(r[5] for r in sonra)} satır")
    # B1b: diğer depolarda 01.08.2026+ CI/CO (bağlam)
    cur.execute(f"""
        SELECT WarehouseCode, InnerProcessCode, {docno}, CAST({SEMA.st_date} AS date), MIN({SEMA.st_created}),
               COUNT(*), SUM(ISNULL(In_Qty1,0)), SUM(ISNULL(Out_Qty1,0))
        FROM trStock WITH(NOLOCK)
        WHERE WarehouseCode <> ? AND InnerProcessCode IN ('CI','CO') AND {SEMA.st_created} >= '2026-08-01'
        GROUP BY WarehouseCode, InnerProcessCode, {docno}, CAST({SEMA.st_date} AS date)
        ORDER BY MIN({SEMA.st_created})""", (WH,))
    log("  B1b) diğer depolarda 01.08.2026'dan beri girilen CI/CO (bağlam):")
    for r in cur.fetchall():
        log(f"   {s(r[0]):4} {s(r[1]):3} | {s(r[2]):15} | belge {s(d(r[3]))} | giriş {s(r[4])[:16]} | {r[5]:>5} satır | "
            f"+{f(r[6]):.0f} −{f(r[7]):.0f}")

    # B2: 02.09+ girilen tüm S02 hareketleri, tip bazında
    tip_sel = ", ".join(SEMA.tip_cols)
    cur.execute(f"""
        SELECT {tip_sel}, COUNT(*), SUM(ISNULL(In_Qty1,0)), SUM(ISNULL(Out_Qty1,0)),
               MIN(CAST({SEMA.st_date} AS date)), MAX(CAST({SEMA.st_date} AS date)),
               SUM(CASE WHEN {SEMA.st_date} <= ? THEN 1 ELSE 0 END)
        FROM trStock WITH(NOLOCK)
        WHERE WarehouseCode = ? AND {SEMA.st_created} >= ?
        GROUP BY {tip_sel} ORDER BY COUNT(*) DESC""", (SAYIM_TARIHI, WH, SONRASI))
    nt = len(SEMA.tip_cols)
    log(f"\n  B2) {SONRASI}+ GİRİLEN {WH} hareketleri, tip bazında (satır | +giriş | −çıkış | belge T aralığı | geri tarihli satır):")
    for r in cur.fetchall():
        t = tuple(s(x) for x in r[:nt])
        log(f"   {r[nt]:>6} | {f(r[nt+1]):>7.0f} | {f(r[nt+2]):>7.0f} | {s(r[nt+3])} → {s(r[nt+4])} | "
            f"geri tarihli {r[nt+5] or 0:>5} | {tip_str(t)}")

    # B3: geri tarihli girişler (belge ≤ 01.09, giriş ≥ 02.09), belge bazında
    cur.execute(f"""
        SELECT {tip_sel}, {docno}, CAST({SEMA.st_date} AS date), CAST({SEMA.st_created} AS date),
               COUNT(*), SUM(ISNULL(In_Qty1,0)), SUM(ISNULL(Out_Qty1,0))
        FROM trStock WITH(NOLOCK)
        WHERE WarehouseCode = ? AND {SEMA.st_date} <= ? AND {SEMA.st_created} >= ?
        GROUP BY {tip_sel}, {docno}, CAST({SEMA.st_date} AS date), CAST({SEMA.st_created} AS date)
        ORDER BY CAST({SEMA.st_created} AS date)""", (WH, SAYIM_TARIHI, SONRASI))
    rows = cur.fetchall()
    log(f"\n  B3) GERİ TARİHLİ girişler (belge ≤ {SAYIM_TARIHI}, giriş ≥ {SONRASI}): {len(rows)} belge")
    for r in rows[:60]:
        t = tuple(s(x) for x in r[:nt])
        log(f"   {s(r[nt]):15} | belge {s(r[nt+1])} | giriş {s(r[nt+2])} | {r[nt+3]:>5} satır | "
            f"+{f(r[nt+4]):.0f} −{f(r[nt+5]):.0f} | {tip_str(t)}")


# ---------------------------------------------------------------- C
@bolum("C) BARKOD → ÜRÜN KİMLİĞİ")
def c_kimlik(cur):
    dim2 = ", b.ItemDim2Code" if SEMA.dim2 else ", NULL"
    satir = {x[0]: x for x in SAYIM}
    cokbarkod = 0
    for parca in chunks(SAYIM, 900):
        vals = ",".join(f"(N'{x[0]}')" for x in parca)
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {vals}) v(Barcode))
            SELECT S.Barcode, b.ItemCode, b.ColorCode, b.ItemDim1Code{dim2}
            FROM S
            OUTER APPLY (SELECT TOP 1 * FROM prItemBarcode bb WITH(NOLOCK)
                         WHERE bb.Barcode = S.Barcode ORDER BY bb.ItemCode) b""")
        for r in cur.fetchall():
            bk = s(r[0])
            _, yeni, eski, model, renk, beden = satir[bk]
            if r[1] is None:
                ESLESMEYEN.append(satir[bk])
                continue
            k = key_of(r[1], r[2], r[3], r[4])
            u = URUN.get(k)
            if u is None:
                u = URUN[k] = {"Key": k, "Barkodlar": [], "Sayim": 0, "SayimEski": 0, "EskiVar": False,
                               "Model": model, "RenkKodu": renk, "Beden": beden}
            else:
                cokbarkod += 1
            u["Barkodlar"].append(bk)
            u["Sayim"] += yeni
            if eski is not None:
                u["SayimEski"] += eski
                u["EskiVar"] = True
    for u in URUN.values():
        u["Barkod"] = u["Barkodlar"][0]
        u["Degisen"] = (u["Sayim"] != u["SayimEski"]) or not u["EskiVar"]
    log(f"  sayım satırı {len(SAYIM)} → Nebim ürünü {len(URUN)} | aynı ürüne düşen ek barkod: {cokbarkod} | "
        f"eşleşmeyen barkod: {len(ESLESMEYEN)}")
    for x in ESLESMEYEN[:60]:
        log(f"   EŞLEŞMEDİ: {x[0]} {x[3]} {x[4]} {x[5]} adet {x[1]}")
    farkli = [u for u in URUN.values() if u["Model"].upper() != u["Key"][0]]
    log(f"  Excel madde kodu ≠ Nebim ItemCode: {len(farkli)}" +
        (" (örn: " + "; ".join(f"{u['Barkod']} {u['Model']}→{u['Key'][0]}" for u in farkli[:8]) + ")" if farkli else ""))


# ---------------------------------------------------------------- D (veri)
def hareketleri_cek(cur):
    kc = ", ".join(key_cols("st"))
    nk = 4 if SEMA.dim2 else 3
    cur.execute(f"""
        SELECT {kc}, SUM(ISNULL(st.In_Qty1,0)) - SUM(ISNULL(st.Out_Qty1,0))
        FROM trStock st WITH(NOLOCK)
        WHERE st.WarehouseCode = ? AND st.{SEMA.st_date} < ? AND st.{SEMA.st_created} < ?
        GROUP BY {kc}""", (WH, PENCERE_BAS, SONRASI))
    for r in cur.fetchall():
        ACILIS[key_of(*r[:nk])] = ACILIS.get(key_of(*r[:nk]), 0.0) + f(r[nk])
    log(f"  açılış bakiyesi ({PENCERE_BAS} öncesi belge, {SONRASI} öncesi giriş): {len(ACILIS)} ürün / "
        f"{sum(ACILIS.values()):.0f} adet")
    tip_sel = ", ".join(f"st.{c}" for c in SEMA.tip_cols)
    tip_sel = (tip_sel + ", ") if tip_sel else ""
    # pencere: belge ≥ PENCERE_BAS  VEYA  giriş ≥ SONRASI (çok eski tarihli ama sayımdan sonra girilmiş kayıtlar da ayrışsın)
    cur.execute(f"""
        SELECT {kc}, {tip_sel}CAST(st.{SEMA.st_date} AS date), CAST(st.{SEMA.st_created} AS date),
               SUM(ISNULL(st.In_Qty1,0)), SUM(ISNULL(st.Out_Qty1,0)), COUNT(*)
        FROM trStock st WITH(NOLOCK)
        WHERE st.WarehouseCode = ? AND (st.{SEMA.st_date} >= ? OR st.{SEMA.st_created} >= ?)
        GROUP BY {kc}, {tip_sel}CAST(st.{SEMA.st_date} AS date), CAST(st.{SEMA.st_created} AS date)""",
                (WH, PENCERE_BAS, SONRASI))
    nt = len(SEMA.tip_cols)
    n = 0
    for r in cur.fetchall():
        k = key_of(*r[:nk])
        t = tuple(s(x) for x in r[nk:nk + nt])
        HAREKET[k].append((t, d(r[nk + nt]), d(r[nk + nt + 1]), f(r[nk + nt + 2]), f(r[nk + nt + 3]), r[nk + nt + 4]))
        n += 1
    log(f"  pencere hareket grubu: {n}; ürün: {len(HAREKET)}")
    lk = ", ".join(key_cols("l"))
    cur.execute(f"""
        SELECT {lk}, h.IsReturn, SUM(l.Qty1)
        FROM trInvoiceLine l WITH(NOLOCK)
        JOIN trInvoiceHeader h WITH(NOLOCK) ON h.InvoiceHeaderID = l.InvoiceHeaderID
        WHERE h.ProcessCode = 'R' AND h.StoreCode = ? AND h.InvoiceDate >= ?
        GROUP BY {lk}, h.IsReturn""", (STORE, SONRASI))
    ns = ni = 0.0
    for r in cur.fetchall():
        k = key_of(*r[:nk])
        if r[nk]:
            SATIS[k][1] += f(r[nk + 1]); ni += f(r[nk + 1])
        else:
            SATIS[k][0] += f(r[nk + 1]); ns += f(r[nk + 1])
    log(f"  {SONRASI}+ perakende ({STORE}): satış {ns:.0f} adet, iade {ni:.0f} adet")


def hesapla(k):
    acilis = ACILIS.get(k, 0.0)
    stok01 = acilis          # belge tarihi ≤ 01.09 olan TÜM hareketler (geri tarihli düzeltme dahil)
    simdi = acilis
    duz_sonra = 0.0          # CI/CO, belge tarihi > 01.09
    duz_giris = 0.0          # CI/CO, GİRİŞ tarihi ≥ 02.09 (belge tarihi ne olursa olsun) = sayım sonrası yapılan düzeltme
    diger_sonra = 0.0
    tip_sonra = defaultdict(float)
    son = None
    for t, belge, giris, qin, qout, n in HAREKET.get(k, []):
        net = qin - qout
        simdi += net
        adj = is_adj(t)
        if belge is None or belge <= SAYIM_TARIHI:
            stok01 += net
        else:
            if adj:
                duz_sonra += net
            else:
                diger_sonra += net
            tip_sonra[t] += net
        if adj and giris and giris >= SONRASI:
            duz_giris += net
        if belge and (son is None or belge > son[0]):
            son = (belge, t, net)
    satis, iade = SATIS.get(k, [0.0, 0.0])
    duz = stok01 + duz_sonra
    return {"Acilis": acilis, "Stok01": stok01, "DuzSonra": duz_sonra, "DuzGiris": duz_giris,
            "Stok01Duz": duz, "Stok01Ham": duz - duz_giris, "SatisSonra": satis, "IadeSonra": iade,
            "DigerSonra": diger_sonra, "StokSimdi": simdi, "TipSonra": dict(tip_sonra), "SonHareket": son}


def satir(u):
    sh = u.get("SonHareket")
    shs = f"{sh[0]} {tip_str(sh[1])} {sh[2]:+.0f}" if sh else "-"
    return (f"   {u['Barkod']} {u['Model']:<13} {u['RenkKodu']:>3} {u['Beden']:>4} | sayım {u['Sayim']:>3} (eski {u['SayimEski']:>3}) | "
            f"Nebim 01.09 ham {u['Stok01Ham']:>4.0f} düz {u['DuzGiris']:>+4.0f} = {u['Stok01Duz']:>4.0f} | FARK {u['Fark']:>+4.0f} | "
            f"satış {u['SatisSonra']:>2.0f} iade {u['IadeSonra']:>2.0f} diğer {u['DigerSonra']:>+3.0f} şimdi {u['StokSimdi']:>4.0f} | son: {shs}")


@bolum("D) ÜRÜN BAZINDA MUTABAKAT")
def d_mutabakat(cur):
    hareketleri_cek(cur)
    for k, u in URUN.items():
        u.update(hesapla(k))
        u["Fark"] = u["Stok01Duz"] - u["Sayim"]
        u["FarkEski"] = u["Stok01Duz"] - u["SayimEski"]
        u["FarkHam"] = u["Stok01Ham"] - u["Sayim"]
        if k not in ACILIS and k not in HAREKET:
            u["Durum"] = f"{WH}'DE HİÇ HAREKET YOK" if u["Sayim"] else "DOĞRU (0=0, hareket yok)"
        elif abs(u["Fark"]) < 1e-9:
            u["Durum"] = "DOĞRU"
        elif u["Fark"] < 0:
            u["Durum"] = "NEBİM EKSİK"
        else:
            u["Durum"] = "NEBİM FAZLA"
    U = list(URUN.values())
    dogru = [u for u in U if abs(u["Fark"]) < 1e-9]
    eksik = [u for u in U if u["Fark"] < -1e-9]
    fazla = [u for u in U if u["Fark"] > 1e-9]
    dogru_eski = [u for u in U if abs(u["FarkEski"]) < 1e-9]
    ham_esit = [u for u in U if abs(u["FarkHam"]) < 1e-9]
    dokunan = [u for u in U if abs(u["DuzGiris"]) > 1e-9]
    log(f"  sayım dosyası: {len(SAYIM)} satır / {sum(x[1] for x in SAYIM)} adet (eski dosya {sum((x[2] or 0) for x in SAYIM)} adet) | "
        f"Nebim'de bulunan ürün: {len(U)} / {sum(u['Sayim'] for u in U)} adet")
    log(f"\n  1) SAYIM ÖNCESİ DURUM — düzeltme HARİÇ Nebim 01.09 stoğu:")
    log(f"     sayımla aynı: {len(ham_esit)} / {len(U)} ürün | Nebim ham toplam {sum(u['Stok01Ham'] for u in U):.0f} adet")
    log(f"     gereken düzeltme (sayım − ham): +{sum(-u['FarkHam'] for u in U if u['FarkHam'] < 0):.0f} giriş ({sum(1 for u in U if u['FarkHam'] < 0)} ürün), "
        f"−{sum(u['FarkHam'] for u in U if u['FarkHam'] > 0):.0f} çıkış ({sum(1 for u in U if u['FarkHam'] > 0)} ürün)")
    log(f"  2) YAPILAN DÜZELTME — {SONRASI}+ girilen CI/CO, sayım ürünlerine dokunan: {len(dokunan)} ürün | "
        f"+{sum(u['DuzGiris'] for u in dokunan if u['DuzGiris'] > 0):.0f} / {sum(u['DuzGiris'] for u in dokunan if u['DuzGiris'] < 0):.0f}")
    log(f"  3) SONUÇ — FARK = (Nebim 01.09 stoğu + düzeltme) − sayım:")
    log(f"     ✓ FARK = 0 (YENİ dosyayla birebir) : {len(dogru):>5} ürün / {sum(u['Sayim'] for u in dogru):>6} adet")
    log(f"     ✗ Nebim EKSİK (FARK < 0)           : {len(eksik):>5} ürün / {-sum(u['Fark'] for u in eksik):>6.0f} adet")
    log(f"     ✗ Nebim FAZLA (FARK > 0)           : {len(fazla):>5} ürün / {sum(u['Fark'] for u in fazla):>6.0f} adet")
    log(f"     Nebim 01.09 (düzeltmeli) toplam, sayım ürünleri: {sum(u['Stok01Duz'] for u in U):.0f} adet  ↔  dosya {sum(u['Sayim'] for u in U)}")
    log(f"     karşılaştırma — ESKİ dosyayla (çanta güncellemesi öncesi) birebir olan: {len(dogru_eski)} ürün")
    if not dokunan:
        log(f"\n  >>> HÜKÜM: {SONRASI}'den sonra {WH}'ye sayım düzeltmesi (CI/CO) GİRİLMEMİŞ → SAYIM NEBİM'E İŞLENMEMİŞ görünüyor.")
    else:
        log(f"\n  >>> HÜKÜM: sayım düzeltmesi GİRİLMİŞ ({len(dokunan)} ürün). Birebir tutan {len(dogru)}/{len(U)} ürün; "
            f"tutmayan {len(eksik)+len(fazla)} ürün aşağıda.")

    deg = [u for u in U if u["Degisen"]]
    log(f"\n  --- ÇANTA GÜNCELLEMESİYLE DEĞİŞEN {len(deg)} ÜRÜN: Nebim hangisini işlemiş? ---")
    ny = ne = nh = 0
    for u in sorted(deg, key=lambda u: (u["Model"], u["RenkKodu"])):
        if abs(u["Fark"]) < 1e-9:
            hangi = "YENİ ile aynı"; ny += 1
        elif abs(u["FarkEski"]) < 1e-9:
            hangi = "ESKİ ile aynı"; ne += 1
        else:
            hangi = "HİÇBİRİ"; nh += 1
        log(f"   {u['Barkod']} {u['Model']:<13} {u['RenkKodu']:>3} | eski {u['SayimEski']:>2} yeni {u['Sayim']:>2} | "
            f"Nebim ham {u['Stok01Ham']:>3.0f} düz {u['DuzGiris']:>+3.0f} = {u['Stok01Duz']:>3.0f} | {hangi} | şimdi {u['StokSimdi']:.0f}")
    log(f"   özet: YENİ ile aynı {ny} · ESKİ ile aynı {ne} · hiçbiri {nh}")

    log(f"\n  --- NEBİM EKSİK (ilk {LISTE_LIMIT}) ---")
    for u in sorted(eksik, key=lambda u: (u["Fark"], u["Barkod"]))[:LISTE_LIMIT]:
        log(satir(u))
    log(f"  (toplam {len(eksik)})")
    log(f"\n  --- NEBİM FAZLA (ilk {LISTE_LIMIT}) ---")
    for u in sorted(fazla, key=lambda u: (-u["Fark"], u["Barkod"]))[:LISTE_LIMIT]:
        log(satir(u))
    log(f"  (toplam {len(fazla)})")
    return eksik, fazla


# ---------------------------------------------------------------- E
def acikla_ekle(cur, hedefler):
    nk = 4 if SEMA.dim2 else 3
    cols = ["ItemCode", "ColorCode", "ItemDim1Code"] + (["ItemDim2Code"] if SEMA.dim2 else [])
    for parca in chunks(hedefler, 400):
        vals = ["(" + ",".join("N'" + x.replace("'", "''") + "'" for x in h["Key"]) + ")" for h in parca]
        cond = " AND ".join(f"bb.{c} = S.{c}" for c in cols)
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {','.join(vals)}) v({','.join(cols)}))
            SELECT {','.join('S.'+c for c in cols)}, b.Barcode, dd.ItemDescription
            FROM S
            OUTER APPLY (SELECT TOP 1 Barcode FROM prItemBarcode bb WITH(NOLOCK) WHERE {cond}) b
            OUTER APPLY (SELECT TOP 1 ItemDescription FROM cdItemDesc dd WITH(NOLOCK)
                         WHERE dd.ItemCode = S.ItemCode AND dd.LangCode='TR') dd""")
        m = {key_of(*r[:nk]): (s(r[nk]), s(r[nk + 1])) for r in cur.fetchall()}
        for h in parca:
            bk, ac = m.get(h["Key"], ("", ""))
            h["Barkod"] = bk or "-"
            h["Aciklama"] = ac


@bolum("E) TERS KONTROL — sayım dosyasında OLMAYAN ama Nebim'de 01.09 stoğu olan ürünler")
def e_ters(cur):
    tum = set(ACILIS) | set(HAREKET)
    for k in tum - set(URUN):
        h = hesapla(k)
        if abs(h["StokSimdi"]) < 1e-9 and abs(h["Stok01Duz"]) < 1e-9 and abs(h["Stok01Ham"]) < 1e-9:
            continue
        h["Key"] = k
        TERS.append(h)
    poz = [h for h in TERS if h["Stok01Duz"] > 1e-9]
    neg = [h for h in TERS if h["Stok01Duz"] < -1e-9]
    ham_poz = [h for h in TERS if h["Stok01Ham"] > 1e-9]
    log(f"  sayımda olmayıp {WH}'de bakiyesi/hareketi olan ürün: {len(TERS)}")
    log(f"   düzeltme ÖNCESİ 01.09 stoğu > 0 : {len(ham_poz)} ürün / {sum(h['Stok01Ham'] for h in ham_poz):.0f} adet")
    log(f"   düzeltme SONRASI 01.09 stoğu > 0: {len(poz)} ürün / {sum(h['Stok01Duz'] for h in poz):.0f} adet  ← sayım tam işlendiyse 0 olmalı")
    log(f"   düzeltme SONRASI 01.09 stoğu < 0: {len(neg)} ürün / {sum(h['Stok01Duz'] for h in neg):.0f} adet")
    tum_toplam = sum(u["Stok01Duz"] for u in URUN.values()) + sum(h["Stok01Duz"] for h in TERS)
    log(f"   NEBİM {WH} 01.09 KAPANIŞ STOĞU (düzeltmeli, TÜM ürünler): {tum_toplam:.0f} adet  ↔  sayım dosyası {sum(x[1] for x in SAYIM)} adet")
    hedef = sorted(poz + neg, key=lambda h: -abs(h["Stok01Duz"]))[:LISTE_LIMIT]
    if hedef:
        acikla_ekle(cur, hedef)
    log(f"\n  --- düzeltme sonrası 01.09 stoğu ≠ 0 olanlar (ilk {LISTE_LIMIT}) ---")
    for h in hedef:
        k = h["Key"]
        log(f"   {h.get('Barkod','-'):13} {k[0]:<13} {k[1]:>3} {k[2]:>4} | ham {h['Stok01Ham']:>4.0f} düz {h['DuzGiris']:>+4.0f} = {h['Stok01Duz']:>4.0f} | "
            f"satış {h['SatisSonra']:>2.0f} | şimdi {h['StokSimdi']:>4.0f} | {h.get('Aciklama','')[:40]}")


# ---------------------------------------------------------------- F
@bolum("F) TUTMAYAN ÜRÜNLER — son 3 hareket + diğer depolardaki stok")
def f_detay(cur, hedefler):
    hedef = sorted(hedefler, key=lambda u: (-abs(u["Fark"]), u["Barkod"]))[:150]
    if not hedef:
        log("  tutmayan ürün yok"); return
    nk = 4 if SEMA.dim2 else 3
    cols = ["ItemCode", "ColorCode", "ItemDim1Code"] + (["ItemDim2Code"] if SEMA.dim2 else [])
    tip_sel = ", ".join(f"st.{c}" for c in SEMA.tip_cols)
    tip_sel = (tip_sel + ", ") if tip_sel else ""
    docno = f"st.{SEMA.docno}" if SEMA.docno else "NULL"
    nt = len(SEMA.tip_cols)
    for parca in chunks(hedef, 150):
        vals = ["(" + ",".join("N'" + x.replace("'", "''") + "'" for x in u["Key"]) + ")" for u in parca]
        cond = " AND ".join(f"st.{c} = S.{c}" for c in cols)
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {','.join(vals)}) v({','.join(cols)}))
            SELECT {','.join('S.'+c for c in cols)}, st.WarehouseCode,
                   SUM(ISNULL(st.In_Qty1,0)) - SUM(ISNULL(st.Out_Qty1,0))
            FROM S JOIN trStock st WITH(NOLOCK) ON {cond}
            GROUP BY {','.join('S.'+c for c in cols)}, st.WarehouseCode""")
        depo = defaultdict(list)
        for r in cur.fetchall():
            if abs(f(r[nk + 1])) > 1e-9:
                depo[key_of(*r[:nk])].append(f"{s(r[nk])}:{f(r[nk+1]):.0f}")
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {','.join(vals)}) v({','.join(cols)}))
            SELECT {','.join('S.'+c for c in cols)}, x.BelgeT, x.GirisT, {', '.join('x.'+c for c in SEMA.tip_cols)}{',' if SEMA.tip_cols else ''}
                   x.DocNo, x.Qin, x.Qout
            FROM S
            OUTER APPLY (SELECT TOP 3 CAST(st.{SEMA.st_date} AS date) AS BelgeT, CAST(st.{SEMA.st_created} AS date) AS GirisT,
                         {tip_sel}{docno} AS DocNo, ISNULL(st.In_Qty1,0) AS Qin, ISNULL(st.Out_Qty1,0) AS Qout
                         FROM trStock st WITH(NOLOCK) WHERE st.WarehouseCode = '{WH}' AND {cond}
                         ORDER BY st.{SEMA.st_created} DESC) x""")
        son = defaultdict(list)
        for r in cur.fetchall():
            if r[nk] is None:
                continue
            t = tuple(s(x) for x in r[nk + 2:nk + 2 + nt])
            son[key_of(*r[:nk])].append(
                f"{s(d(r[nk]))}(giriş {s(d(r[nk+1]))}) {tip_str(t)} {s(r[nk+2+nt])} +{f(r[nk+3+nt]):.0f}-{f(r[nk+4+nt]):.0f}")
        for u in parca:
            u["DigerDepolar"] = " ".join(depo.get(u["Key"], [])) or "-"
            u["Son3"] = " || ".join(son.get(u["Key"], [])) or f"{WH}'de hareket yok"
    for u in hedef:
        log(f"   {u['Barkod']} {u['Model']} {u['RenkKodu']} {u['Beden']} | sayım {u['Sayim']} Nebim01.09 {u['Stok01Duz']:.0f} FARK {u['Fark']:+.0f} şimdi {u['StokSimdi']:.0f} "
            f"| depolar: {u['DigerDepolar']} | son: {u['Son3']}")


# ---------------------------------------------------------------- G
@bolum("G) CSV")
def g_csv():
    kolon = ["Barkod", "Barkodlar", "Model", "RenkKodu", "Beden", "Sayim", "SayimEski", "Degisen", "ItemCode", "ColorCode",
             "Dim1", "Dim2", "Durum", "Acilis", "Stok01Ham", "DuzGiris", "Stok01Duz", "Fark", "FarkEski", "FarkHam",
             "SatisSonra", "IadeSonra", "DigerSonra", "StokSimdi", "SonHareket", "DigerDepolar", "Son3", "Aciklama"]

    def hucre(x):
        if x is None:
            return ""
        if isinstance(x, float):
            return f"{x:.4f}".rstrip("0").rstrip(".")
        if isinstance(x, (list, tuple)):
            return " ".join(str(y) for y in x)
        return str(x).replace(";", ",").replace("\n", " ")

    def rows_of(items, ters=False):
        out = [";".join(kolon)]
        for v in items:
            v = dict(v)
            k = v["Key"]
            v.update({"ItemCode": k[0], "ColorCode": k[1], "Dim1": k[2], "Dim2": (k[3] if SEMA.dim2 else "")})
            if ters:
                v.update({"Model": k[0], "RenkKodu": k[1], "Beden": k[2], "Sayim": 0, "SayimEski": 0,
                          "Durum": "SAYIMDA YOK", "Fark": v["Stok01Duz"], "FarkHam": v["Stok01Ham"]})
            sh = v.get("SonHareket")
            if sh:
                v["SonHareket"] = f"{sh[0]} {tip_str(sh[1])} {sh[2]:+.0f}"
            out.append(";".join(hucre(v.get(c)) for c in kolon))
        return out

    for ad, satirlar in ((f"{AD}-SONUC.csv", rows_of(sorted(URUN.values(), key=lambda u: u["Barkod"]))),
                         (f"{AD}-TERS.csv", rows_of(sorted(TERS, key=lambda h: -abs(h["Stok01Duz"])), True))):
        try:
            with open(ad, "w", encoding="utf-8-sig") as fh:
                fh.write("\n".join(satirlar))
            log(f"  {ad} yazıldı ({len(satirlar)-1} satır).")
        except Exception as e:
            log(f"  {ad} yazılamadı: {e}")


def main():
    from satis_kopru import load_config, connect
    cfg = load_config()
    log(f">>> KEŞİF 48 — Mağusa ({WH}) 01.09.2026 sayımı Nebim'e işlendi mi? (salt-okunur)")
    log(f"    sayım dosyası {len(SAYIM)} satır / {sum(x[1] for x in SAYIM)} adet · depo {WH} · sayım {SAYIM_TARIHI} · "
        f"çalıştırma {datetime.now():%Y-%m-%d %H:%M}")
    conn = connect(cfg)
    cur = conn.cursor()
    a_sema(cur)
    b_belgeler(cur)
    c_kimlik(cur)
    res = d_mutabakat(cur)
    e_ters(cur)
    f_detay(cur, (res[0] + res[1]) if res else [])
    g_csv()
    log(f"\n>>> KEŞİF 48 TAMAM. {AD}-CIKTI.txt metnini Claude'a yapıştır; {AD}-SONUC.csv + {AD}-TERS.csv dosyalarını AnyDesk ile Mac'e gönder.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        log(traceback.format_exc())
    try:
        with open(f"{AD}-CIKTI.txt", "w", encoding="utf-8") as fh:
            fh.write("\n".join(OUT))
        print(f"\n>>> {AD}-CIKTI.txt yazildi. <<<")
    except Exception as e:
        print("yazilamadi:", e)
